insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-01', 1, 'pilihan_ganda', 'Hasil dari 450 + 125 × 4 - 300 adalah ...', null, null, 5, '"C"'::jsonb, 'Operasi perkalian didahulukan: 125 × 4 = 500. Kemudian 450 + 500 - 300 = 950 - 300 = 650.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "600"}, {"id": "opt-2", "label": "B", "teks": "625"}, {"id": "opt-3", "label": "C", "teks": "650"}, {"id": "opt-4", "label": "D", "teks": "700"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-02', 2, 'pilihan_ganda', 'Sebuah taman berbentuk persegi panjang berukuran panjang 24 meter dan lebar 18 meter. Di sekeliling taman akan ditanami pohon palem dengan jarak antar pohon 3 meter. Jumlah pohon palem yang dibutuhkan adalah ...', null, null, 5, '"B"'::jsonb, 'Keliling = 2 × (24 + 18) = 2 × 42 = 84 meter. Jumlah pohon = 84 / 3 = 28 pohon.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "26 pohon"}, {"id": "opt-2", "label": "B", "teks": "28 pohon"}, {"id": "opt-3", "label": "C", "teks": "32 pohon"}, {"id": "opt-4", "label": "D", "teks": "36 pohon"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-03', 3, 'pilihan_ganda', 'Bagian tumbuhan yang berfungsi menyerap air dan zat hara dari dalam tanah serta memperkokoh berdirinya tanaman adalah ...', null, null, 5, '"A"'::jsonb, 'Akar berfungsi menyerap air dan garam mineral dari dalam tanah serta menunjang berdirinya tumbuhan.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Akar"}, {"id": "opt-2", "label": "B", "teks": "Batang"}, {"id": "opt-3", "label": "C", "teks": "Daun"}, {"id": "opt-4", "label": "D", "teks": "Bunga"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-04', 4, 'pilihan_ganda', 'Proses perubahan wujud benda dari padat langsung menjadi gas tanpa melalui fase cair disebut ...', null, null, 5, '"D"'::jsonb, 'Menyublim adalah perubahan wujud zat dari padat langsung menjadi gas, contohnya kapur barus.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Mencair"}, {"id": "opt-2", "label": "B", "teks": "Menguap"}, {"id": "opt-3", "label": "C", "teks": "Mengembun"}, {"id": "opt-4", "label": "D", "teks": "Menyublim"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-05', 5, 'pilihan_ganda', 'Ide pokok atau gagasan utama dalam sebuah paragraf biasanya terdapat pada ...', null, null, 5, '"B"'::jsonb, 'Ide pokok paragraf termuat dalam kalimat utama, yang dapat berada di awal (deduktif), akhir (induktif), atau campuran.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Kalimat penjelas"}, {"id": "opt-2", "label": "B", "teks": "Kalimat utama"}, {"id": "opt-3", "label": "C", "teks": "Kalimat pengembang terakhir"}, {"id": "opt-4", "label": "D", "teks": "Judul bacaan"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-06', 6, 'pilihan_ganda', 'Perhatikan deret bilangan berikut: 3, 7, 15, 31, 63, ... . Bilangan berikutnya pada deret tersebut adalah ...', null, null, 5, '"C"'::jsonb, 'Pola deret: n × 2 + 1. 3×2+1=7; 7×2+1=15; 15×2+1=31; 31×2+1=63; 63×2+1=127.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "96"}, {"id": "opt-2", "label": "B", "teks": "124"}, {"id": "opt-3", "label": "C", "teks": "127"}, {"id": "opt-4", "label": "D", "teks": "135"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-07', 7, 'pilihan_ganda', 'Organ tubuh manusia yang berfungsi memompa darah ke seluruh tubuh melalui pembuluh darah adalah ...', null, null, 5, '"B"'::jsonb, 'Jantung bertindak sebagai pompa yang mengedarkan darah kaya oksigen dan nutrisi ke seluruh jaringan tubuh.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Paru-paru"}, {"id": "opt-2", "label": "B", "teks": "Jantung"}, {"id": "opt-3", "label": "C", "teks": "Hati"}, {"id": "opt-4", "label": "D", "teks": "Ginjal"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-08', 8, 'pilihan_ganda', 'Semboyan bangsa Indonesia "Bhinneka Tunggal Ika" diambil dari kitab Sutasoma karangan ...', null, null, 5, '"A"'::jsonb, 'Kitab Sutasoma ditulis oleh Mpu Tantular pada zaman Kerajaan Majapahit abad ke-14.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Mpu Tantular"}, {"id": "opt-2", "label": "B", "teks": "Mpu Prapanca"}, {"id": "opt-3", "label": "C", "teks": "Mpu Sedah"}, {"id": "opt-4", "label": "D", "teks": "Mpu Panuluh"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-09', 9, 'pilihan_ganda', 'FPB (Faktor Persekutuan Terbesar) dan KPK (Kelipatan Persekutuan Terkecil) dari bilangan 36 dan 48 berturut-turut adalah ...', null, null, 5, '"A"'::jsonb, '36 = 2² × 3², 48 = 2⁴ × 3. FPB = 2² × 3 = 12. KPK = 2⁴ × 3² = 16 × 9 = 144.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "12 dan 144"}, {"id": "opt-2", "label": "B", "teks": "6 dan 144"}, {"id": "opt-3", "label": "C", "teks": "12 dan 96"}, {"id": "opt-4", "label": "D", "teks": "18 dan 144"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-10', 10, 'pilihan_ganda', 'Gaya tarik bumi yang menyebabkan semua benda bermassa jatuh ke permukaan bumi dinamakan gaya ...', null, null, 5, '"D"'::jsonb, 'Gaya gravitasi adalah gaya tarik-menarik antarpartikel yang memiliki massa di alam semesta.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Pegas"}, {"id": "opt-2", "label": "B", "teks": "Gesek"}, {"id": "opt-3", "label": "C", "teks": "Magnet"}, {"id": "opt-4", "label": "D", "teks": "Gravitasi"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-11', 11, 'pilihan_ganda', 'Sebuah mobil melaju dengan kecepatan rata-rata 60 km/jam dari kota P ke kota Q. Jika jarak kedua kota tersebut adalah 150 km dan mobil berangkat pukul 07.30, maka mobil akan tiba di kota Q pada pukul ...', null, null, 5, '"B"'::jsonb, 'Waktu tempuh = 150 km / 60 km/jam = 2,5 jam = 2 jam 30 menit. Tiba = 07.30 + 02.30 = 10.00.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "09.30"}, {"id": "opt-2", "label": "B", "teks": "10.00"}, {"id": "opt-3", "label": "C", "teks": "10.30"}, {"id": "opt-4", "label": "D", "teks": "11.00"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-12', 12, 'pilihan_ganda', 'Hubungan timbal balik antara dua makhluk hidup di mana satu pihak diuntungkan dan pihak lain tidak dirugikan maupun diuntungkan disebut simbiosis ...', null, null, 5, '"B"'::jsonb, 'Simbiosis komensalisme menguntungkan salah satu pihak tanpa merugikan pihak lain (contoh: ikan remora dan hiu).', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Mutualisme"}, {"id": "opt-2", "label": "B", "teks": "Komensalisme"}, {"id": "opt-3", "label": "C", "teks": "Parasitisme"}, {"id": "opt-4", "label": "D", "teks": "Amensalisme"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-13', 13, 'pilihan_ganda', 'Kutub-kutub magnet yang senama jika didekatkan akan saling ...', null, null, 5, '"A"'::jsonb, 'Sifat magnet: kutub senama tolak-menolak, kutub tidak senama tarik-menarik.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Tolak-menolak"}, {"id": "opt-2", "label": "B", "teks": "Tarik-menarik"}, {"id": "opt-3", "label": "C", "teks": "Menempel kuat"}, {"id": "opt-4", "label": "D", "teks": "Tidak bereaksi"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-14', 14, 'pilihan_ganda', 'Penulisan kata baku yang tepat menurut Pedoman Umum Ejaan Bahasa Indonesia (PUEBI) adalah ...', null, null, 5, '"C"'::jsonb, 'Kata baku yang tepat adalah "Praktik", "Kualitas", "Objektif". Bukan praktek/kwalitas.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Praktek"}, {"id": "opt-2", "label": "B", "teks": "Kwalitas"}, {"id": "opt-3", "label": "C", "teks": "Praktik"}, {"id": "opt-4", "label": "D", "teks": "Objektiip"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-15', 15, 'pilihan_ganda', 'Perhatikan piramida makanan: Tumbuhan hijau menduduki posisi sebagai ...', null, null, 5, '"A"'::jsonb, 'Tumbuhan hijau mampu menghasilkan makanannya sendiri melalui fotosintesis, sehingga bertindak sebagai produsen.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Produsen"}, {"id": "opt-2", "label": "B", "teks": "Konsumen tingkat I"}, {"id": "opt-3", "label": "C", "teks": "Konsumen tingkat II"}, {"id": "opt-4", "label": "D", "teks": "Dekomposer"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-16', 16, 'pilihan_ganda', 'Jika 3 kg mangga harganya Rp45.000, maka harga 7 kg mangga yang sama adalah ...', null, null, 5, '"B"'::jsonb, 'Harga per kg = Rp45.000 / 3 = Rp15.000. Harga 7 kg = 7 × Rp15.000 = Rp105.000.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Rp95.000"}, {"id": "opt-2", "label": "B", "teks": "Rp105.000"}, {"id": "opt-3", "label": "C", "teks": "Rp115.000"}, {"id": "opt-4", "label": "D", "teks": "Rp120.000"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-17', 17, 'pilihan_ganda', 'Planet terbesar dalam tata surya kita yang juga memiliki badai besar terkenal bernama "Bintik Merah Raksasa" adalah ...', null, null, 5, '"C"'::jsonb, 'Yupiter (Jupiter) adalah planet terbesar di tata surya.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Mars"}, {"id": "opt-2", "label": "B", "teks": "Saturnus"}, {"id": "opt-3", "label": "C", "teks": "Yupiter"}, {"id": "opt-4", "label": "D", "teks": "Neptunus"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-18', 18, 'pilihan_ganda', 'Pernyataan berikut yang merupakan hak asasi sebagai warga negara dalam bidang pendidikan di Indonesia diatur dalam UUD 1945 pasal ...', null, null, 5, '"D"'::jsonb, 'Pasal 31 UUD 1945 menyatakan bahwa setiap warga negara berhak mendapat pendidikan.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Pasal 27"}, {"id": "opt-2", "label": "B", "teks": "Pasal 28"}, {"id": "opt-3", "label": "C", "teks": "Pasal 30"}, {"id": "opt-4", "label": "D", "teks": "Pasal 31"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-19', 19, 'pilihan_ganda', 'Rata-rata nilai ulangan matematika dari 5 siswa adalah 82. Jika nilai siswa keenam digabungkan, nilai rata-ratanya menjadi 84. Nilai siswa keenam tersebut adalah ...', null, null, 5, '"C"'::jsonb, 'Jumlah 5 siswa = 5 × 82 = 410. Jumlah 6 siswa = 6 × 84 = 504. Nilai siswa ke-6 = 504 - 410 = 94.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "88"}, {"id": "opt-2", "label": "B", "teks": "90"}, {"id": "opt-3", "label": "C", "teks": "94"}, {"id": "opt-4", "label": "D", "teks": "96"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-20', 20, 'pilihan_ganda', 'Sikap toleransi dan saling menghormati perbedaan suku, agama, dan ras merupakan cerminan pengamalan Pancasila sila ke-...', null, null, 5, '"B"'::jsonb, 'Sila ketiga "Persatuan Indonesia" menempatkan kesatuan, persatuan, serta kepentingan bangsa dan negara di atas kepentingan pribadi atau golongan dengan semangat Bhinneka Tunggal Ika.', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "Pertama"}, {"id": "opt-2", "label": "B", "teks": "Ketiga"}, {"id": "opt-3", "label": "C", "teks": "Keempat"}, {"id": "opt-4", "label": "D", "teks": "Kelima"}]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, no_urut, tipe, soal, gambar, posisi_gambar, bobot, kunci, pembahasan, status, options) values ('Q-21', 21, 'pilihan_ganda', 'asdasdas', null, 'atas', 5, '"A"'::jsonb, 'asdsad', 'aktif', '[{"id": "opt-1", "label": "A", "teks": "dasdas"}, {"id": "opt-2", "label": "B", "teks": "asdasd"}, {"id": "opt-3", "label": "C", "teks": "asdasd"}, {"id": "opt-4", "label": "D", "teks": "asdasd"}]'::jsonb) on conflict (id) do nothing;
